          color: #FFFFFF;
        }

        button.UpcartDesignSettings__button:hover span,
        input.UpcartDesignSettings__button:hover,
        .UpcartDesignSettings__button:hover,
        .UpcartDesignSettings__button:hover span {
          color: #e9e9e9 !important;
        }

